mapper.select:
SELECT s.course_id, s.sec_id, s.semester, s.year, s.building, s.room_number, s.time_slot_id, c.title AS course_title, (SELECT GROUP_CONCAT(i.name SEPARATOR '、') FROM teaches t JOIN instructor i ON t.ID = i.ID WHERE t.course_id = s.course_id AND t.sec_id = s.sec_id AND t.semester = s.semester AND t.year = s.year) AS instructor_names, (SELECT COUNT(*) FROM takes k WHERE k.course_id = s.course_id AND k.sec_id = s.sec_id AND k.semester = s.semester AND k.year = s.year) AS enrolled, cl.capacity FROM section s LEFT JOIN course c ON s.course_id = c.course_id LEFT JOIN classroom cl ON s.building = cl.building AND s.room_number = cl.room_number
AND s.semester = #{semester}
AND s.year = #{year}
AND s.course_id = #{courseId}
ORDER BY s.year DESC, s.semester, s.course_id, s.sec_id
